NOTES={}
def add(d):NOTES.update({IDS[k]:v for k,v in d.items()})
def abstract(i):
 ident=IDS[i];url='https://www.nature.com/articles/'+ident
 raw=cached_html(ident,url,fetch=False)
 p=parse_publisher(raw,url) if raw else {'sections':{}}
 t=next((v for k,v in p['sections'].items() if 'abstract' in k.lower()),'')
 if not t:
  for base in [ROOT/'research-cache/npj',Path('/Users/youngbean/Documents/ChatGPT/雅思/npj-digital-medicine/research-cache')]:
   f=base/(ident+'.txt')
   if f.exists():
    raw=f.read_text(errors='replace');match=re.search(r'Abstract\s+(.*?)(?:\nIntroduction|\nBackground|\n[A-Z][a-z]+ [A-Z][a-z]+)',raw,re.S)
    if match:t=re.sub(r'\s+',' ',match.group(1));break
 return t
def main():
 if len(sys.argv)>1 and sys.argv[1]=='--show':
  meta={p['id']:p for p in json.loads((ROOT/'data/reviews/npj.json').read_text())}
  for i in range(int(sys.argv[2]),int(sys.argv[3])):
   t=abstract(i);print(i,IDS[i],meta.get(IDS[i],{}).get('title'));print(t if len(t)<2100 else t[:1550]+' [...] '+t[-550:])
  return
 out=[]
 def clean(t):
  t=re.sub(r'\b(Evaluates|from|Screening|and|reaches|Among|Tests|approximately|Analyzes|across|about|Filters|for|Nearly|Benchmarks|than|Maps|with|Identifies|among|in|on|by|of|involving|Reviews|supports|Testing|against|Only|Across|support|raw|Provides|discriminate)(?=\d)',r'\1 ',t)
  return re.sub(r'(?<=\d)(?=million\b)', ' ', t)
 for ident,(question,method,finding,limitation) in NOTES.items():
  question,method,finding,limitation=map(clean,(question,method,finding,limitation))
  out.append({'id':ident,'research_problem':question,'problem_is_excerpt':False,'ai_method':method,'study_summary':finding,'outcome_summary':finding,'limitations':[limitation],'curation_level':'curated','review_level':'abstract','field_status':{'research_problem':'manually_interpreted_original_abstract','ai_method':'manually_interpreted_original_abstract','study_summary':'manually_interpreted_original_abstract','limitations':'manually_interpreted_design_boundary'},'manual_review':'Original publisher abstract read and interpreted; no full-text review claimed.','evidence_links':[{'label':'Original abstract','url':'https://www.nature.com/articles/'+ident+'#Abs1'}]})
 p=ROOT/'data/enrichment/npj-older-manual.json';p.write_text(json.dumps(out,ensure_ascii=False,indent=2));print('saved',len(out),'of',len(IDS))
